function initCoastlineViz(){const t=document.getElementById("coastline-viz-bg");if(!t)return;t.innerHTML='\n    <svg viewBox="0 0 1440 320" preserveAspectRatio="none" style="width: 100%; height: 100%;">\n        <path fill="#0083b0" fill-opacity="0.3" d="M0,192L48,197.3C96,203,192,213,288,229.3C384,245,480,267,576,250.7C672,235,768,181,864,181.3C960,181,1056,235,1152,234.7C1248,235,1344,181,1392,154.7L1440,128L1440,320L1392,320C1344,320,1248,320,1152,320C1056,320,960,320,864,320C768,320,672,320,576,320C480,320,384,320,288,320C192,320,96,320,48,320L0,320Z"></path>\n        <path fill="#00b4db" fill-opacity="0.5" d="M0,96L48,112C96,128,192,160,288,160C384,160,480,128,576,122.7C672,117,768,139,864,149.3C960,160,1056,160,1152,138.7C1248,117,1344,75,1392,53.3L1440,32L1440,320L1392,320C1344,320,1248,320,1152,320C1056,320,960,320,864,320C768,320,672,320,576,320C480,320,384,320,288,320C192,320,96,320,48,320L0,320Z"></path>\n    </svg>'}function initRiverCompare(){const t=document.getElementById("toggle-river-btn"),e=document.querySelector(".ancient-map"),i=document.querySelector(".modern-map");if(!t||!e||!i)return;let n=!0;t.addEventListener("click",()=>{n?(e.classList.remove("active"),i.classList.add("active"),t.textContent="Toggle Ancient View"):(i.classList.remove("active"),e.classList.add("active"),t.textContent="Toggle Modern View"),n=!n})}function initTimeline(){const t=document.getElementById("timeline-container");if(!t)return;[{date:"3rd Century BCE",title:"Mauryan Era Port",desc:"Tamralipta flourishes as a prominent eastern port under Ashoka, facilitating trade and the spread of Buddhism."},{date:"5th Century CE",title:"Fa-Hien's Visit",desc:"Chinese pilgrim Fa-Hien visits, describing the port with 24 Buddhist monasteries and documenting its maritime links to Sri Lanka."},{date:"7th Century CE",title:"Xuanzang and I-Tsing",desc:"Xuanzang notes its commercial wealth and agricultural richness. I-Tsing arrives by sea from China via Srivijaya."},{date:"8th-12th Century CE",title:"Pala & Sena Dynasties",desc:"Continued trade dominance with Southeast Asia, evidenced by rich archaeological finds of pottery and coins."},{date:"Post-12th Century CE",title:"Port Decline",desc:"Siltation of the Rupnarayan river and shifting coastlines gradually render the port inaccessible to large ships, leading to its decline."}].forEach(e=>{const i=document.createElement("div");i.classList.add("timeline-event"),i.innerHTML=`\n            <span class="timeline-date">${e.date}</span>\n            <h3 class="timeline-title">${e.title}</h3>\n            <p class="timeline-desc">${e.desc}</p>\n        `,t.appendChild(i)})}function initTradeMap(){const t=document.getElementById("trade-map-svg");if(!t)return;const e={ports:[{id:"tamralipta",name:"Tamralipta",x:200,y:100,r:8},{id:"srilanka",name:"Sri Lanka (Tamraparni)",x:150,y:350,r:6},{id:"suvarnabhumi",name:"Suvarnabhumi (SE Asia)",x:600,y:250,r:7},{id:"china",name:"China (Guangzhou)",x:750,y:100,r:6}],routes:[{from:"tamralipta",to:"srilanka"},{from:"tamralipta",to:"suvarnabhumi"},{from:"srilanka",to:"suvarnabhumi"},{from:"suvarnabhumi",to:"china"}]};e.routes.forEach(i=>{const n=e.ports.find(t=>t.id===i.from),a=e.ports.find(t=>t.id===i.to);if(n&&a){const e=document.createElementNS("http://www.w3.org/2000/svg","line");e.setAttribute("x1",n.x),e.setAttribute("y1",n.y),e.setAttribute("x2",a.x),e.setAttribute("y2",a.y),e.classList.add("maritime-route"),t.appendChild(e)}}),e.ports.forEach(e=>{const i=document.createElementNS("http://www.w3.org/2000/svg","circle");i.setAttribute("cx",e.x),i.setAttribute("cy",e.y),i.setAttribute("r",e.r),i.classList.add("port-node");const n=document.createElementNS("http://www.w3.org/2000/svg","text");n.setAttribute("x",e.x+12),n.setAttribute("y",e.y+5),n.classList.add("port-label"),n.textContent=e.name,t.appendChild(i),t.appendChild(n)})}document.addEventListener("DOMContentLoaded",()=>{initCoastlineViz(),initRiverCompare(),initTimeline(),initTradeMap()});